import { create } from 'zustand';
export const useBookmarksStore = create(set => ({
  bmarks: [],
  hydrated: false,
  setAll: bmarks => {
    set({
      bmarks,
      hydrated: true
    });
  },
  removeById: bid => {
    set(s => ({
      bmarks: s.bmarks.filter(b => b.bid !== bid)
    }));
  },
  upsert: bm => {
    set(s => ({
      bmarks: s.bmarks.map(b => b.bid === bm.bid ? bm : b)
    }));
  }
}));