export async function editNote(note) {
  const res = await request('POST', 'api/note/add', {
    headers: {
      'content-type': 'application/json'
    },
    body: JSON.stringify(note)
  });
  if (!res.ok) return {
    ok: false,
    status: res.status,
    bodyText: await res.text(),
    note: null
  };
  const updated = await res.json();
  return {
    ok: true,
    status: res.status,
    bodyText: '',
    note: updated
  };
}
