export async function resetApiKey() {
  const res = await request('POST', 'Settings/apikey');
  if (res.ok) {
    try {
      const data = await res.json();
      return {
        ok: true,
        status: res.status,
        apiKey: data.apiKey
      };
    } catch {
      return {
        ok: true,
        status: res.status
      };
    }
  }
  return {
    ok: false,
    status: res.status,
    bodyText: await res.text()
  };
}
