// Paths relative to the document's `<base href>` (the approot). Exports are plain
// authenticated GET downloads; anchors point at these directly.
export const exportPaths = {
  bookmarksJson: 'Settings/export/bookmarks/json',
  bookmarksHtml: 'Settings/export/bookmarks/netscape',
  notesJson: 'Settings/export/notes/json'
};
async function importFile(path, contentType, body) {
  const res = await request('POST', path, {
    headers: {
      'content-type': contentType
    },
    body,
    timeout: 300_000
  });
  if (res.ok) {
    try {
      const data = await res.json();
      return {
        ok: true,
        status: res.status,
        imported: data.imported
      };
    } catch {
      return {
        ok: true,
        status: res.status
      };
    }
  }
  return {
    ok: false,
    status: res.status,
    bodyText: await res.text()
  };
}
export const importBookmarks = text => importFile('Settings/import/bookmarks/json', 'application/json', text);
export const importFirefox = text => importFile('Settings/import/bookmarks/firefox', 'application/json', text);
export const importNetscape = text => importFile('Settings/import/bookmarks/netscape', 'text/plain', text);
export const importNotes = jsonArray => importFile('Settings/import/notes/json', 'application/json', jsonArray);
export async function logout() {
  const a = app();
  await request('POST', a.authRlogoutR);
  window.location.reload();
}