export function fromNow(locale = navigator.language, date) {
  const target = date instanceof Date ? date.getTime() : new Date(date).getTime();
  const diff = target - Date.now();
  const abs = Math.abs(diff);
  const units = [['year', 365 * 24 * 60 * 60 * 1000], ['month', 30 * 24 * 60 * 60 * 1000], ['day', 24 * 60 * 60 * 1000], ['hour', 60 * 60 * 1000], ['minute', 60 * 1000], ['second', 1000]];
  const rtf = new Intl.RelativeTimeFormat(locale, {
    numeric: 'auto'
  });
  for (const [unit, ms] of units) {
    if (abs >= ms || unit === 'second') {
      return rtf.format(Math.round(diff / ms), unit);
    }
  }

  // Unreachable, but satisfies TypeScript.
  return '';
}
export function shdatetime(lang, dateString) {
  return new Date(dateString).toLocaleString(lang, {
    dateStyle: 'full',
    timeStyle: 'long'
  });
}
export function toLocaleDateString(lang, dateString) {
  return new Date(dateString).toLocaleDateString(lang, {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
}
